def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def main():
    n = int(input().strip())
    tiles = list(map(int, input().strip().split()))

    # Count the number of 2s in the sequence
    num_twos = tiles.count(2)

    # Create the permutation with more 2s at the beginning to maximize prime prefix sums
    result = [2] * num_twos + [1] * (n - num_twos)

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
